// Compile-Time Polymorphism: Static Dispatch (No VTable)
template <typename Policy>
void process_data(Policy& p) {
    // Static binding: Compiler knows target method at compile time
    p.transform(); // Often fully inlined
}

struct FastPolicy {
    void transform() const { /* optimized logic */ }
};

// Memory: No vptr overhead. Function instantiated per type (Code Bloat risk).
// Performance: Zero runtime overhead, maximum optimization/inlining potential.

